          prints the TID
  refund  --mid MID --batch BID FILE
          FILE: one line per refund: TID<TAB>AMOUNT[<TAB>AUX]
          AUX: optional, [A-Za-z0-9-], 1..24 chars
          prints "accepted N"
  status  --batch BID
          refund no, tid, amount, aux (tab separated)
  txn     TID
  --version

environment:
  PGSIM_HOME   state directory (required)

